import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class ReadBytes {
    public static void main(String[] args) throws IOException {
        // No decoding. The array holds exactly the bytes that sit on disk.
        byte[] data = Files.readAllBytes(Path.of("logo.png"));

        // Java bytes are signed, so mask one before printing it as 0..255.
        System.out.println(data.length + " bytes, first=" + (data[0] & 0xFF));
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class CopyBytes {
    public static void main(String[] args) throws IOException {
        Path source = Path.of("logo.png");
        Path target = Path.of("out", "logo-copy.png");

        // Read and write use bytes on both sides, so nothing is decoded.
        byte[] data = Files.readAllBytes(source);
        Files.createDirectories(target.getParent());
        Files.write(target, data);

        System.out.println(Files.size(target) + " bytes written");
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

public class ArchiveReport {
    public static void main(String[] args) throws IOException {
        Path report = Path.of("out", "report.txt");
        Path archive = Path.of("out", "archive", "report.txt");

        Files.createDirectories(report.getParent());
        Files.writeString(report, "rows=3\n");
        Files.createDirectories(archive.getParent());

        // REPLACE_EXISTING turns the second run from an exception into an overwrite.
        Files.copy(report, archive, StandardCopyOption.REPLACE_EXISTING);

        System.out.println("copied " + Files.size(archive) + " bytes");
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

public class MarkProcessed {
    public static void main(String[] args) throws IOException {
        Path inbox = Path.of("inbox", "bookings.csv");
        Path done = Path.of("done", "bookings.csv");

        Files.createDirectories(inbox.getParent());
        Files.writeString(inbox, "hotel_id,city\n1,Budapest\n");
        Files.createDirectories(done.getParent());

        // Rename inside one filesystem. REPLACE_EXISTING clears yesterday's file.
        Files.move(inbox, done, StandardCopyOption.REPLACE_EXISTING);

        System.out.println(Files.exists(inbox) + " " + Files.exists(done));
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class CleanExports {
    public static void main(String[] args) throws IOException {
        Path old = Path.of("out", "old-report.txt");

        Files.createDirectories(old.getParent());
        Files.writeString(old, "stale\n");

        // First call removes the file and returns true.
        boolean first = Files.deleteIfExists(old);

        // Second call finds nothing, returns false, throws nothing.
        boolean second = Files.deleteIfExists(old);

        System.out.println(first + " " + second + " exists=" + Files.exists(old));
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class ListTextFiles {
    public static void main(String[] args) throws IOException {
        Path root = Path.of("data");
        Files.createDirectories(root.resolve("2026"));
        Files.writeString(root.resolve("notes.txt"), "a\n");
        Files.writeString(root.resolve("2026").resolve("jan.txt"), "b\n");

        List<Path> files;
        // Depth 1 means the direct children of root.
        try (Stream<Path> paths = Files.walk(root, 1)) {
            files = paths.filter(Files::isRegularFile)
                         .sorted()
                         .collect(Collectors.toList());
        }

        for (Path file : files) {
            System.out.println(root.relativize(file) + " " + Files.size(file));
        }
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class DropScratch {
    public static void main(String[] args) throws IOException {
        Path root = Path.of("scratch");
        Files.createDirectories(root.resolve("a").resolve("b"));
        Files.writeString(root.resolve("a").resolve("b").resolve("x.txt"), "x\n");

        // Collect first. Deleting while the walk stream is open breaks the walk.
        List<Path> victims;
        try (Stream<Path> paths = Files.walk(root)) {
            victims = paths.sorted(Comparator.reverseOrder()).collect(Collectors.toList());
        }

        int deleted = 0;
        for (Path path : victims) {
            try {
                Files.delete(path);
                deleted++;
            } catch (IOException e) {
                // One locked file must not stop the cleanup of the rest.
                System.out.println("kept " + path + ": " + e.getMessage());
            }
        }

        System.out.println("deleted " + deleted + " path(s), root exists=" + Files.exists(root));
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

public class SafeWrite {
    public static void main(String[] args) throws IOException {
        Path out = Path.of("out");
        Files.createDirectories(out);

        // Same folder as the target, so the later move is a rename.
        Path tmp = Files.createTempFile(out, "report-", ".tmp");
        try {
            Files.writeString(tmp, "rows=3\n", StandardCharsets.UTF_8);
            Files.move(tmp, out.resolve("report.txt"), StandardCopyOption.REPLACE_EXISTING);
        } finally {
            // Harmless after a successful move, required after a failed one.
            Files.deleteIfExists(tmp);
        }

        System.out.println(Files.readString(out.resolve("report.txt")).trim());
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.nio.file.attribute.FileTime;

public class DescribeFile {
    public static void main(String[] args) throws IOException {
        Path file = Path.of("out", "report.txt");
        Files.createDirectories(file.getParent());
        Files.writeString(file, "rows=3\n");

        // One call, one snapshot: type, size and both timestamps.
        BasicFileAttributes attrs =
                Files.readAttributes(file, BasicFileAttributes.class);

        FileTime modified = attrs.lastModifiedTime();
        System.out.println(file.getFileName() + " " + attrs.size() + " bytes");
        System.out.println("dir=" + attrs.isDirectory()
                + " regular=" + attrs.isRegularFile()
                + " modified=" + modified.toInstant());
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

public class VerifyCopy {
    public static void main(String[] args) throws IOException {
        Path original = Path.of("out", "report.txt");
        Path copy = Path.of("out", "report-copy.txt");

        Files.createDirectories(original.getParent());
        Files.writeString(original, "rows=3\n");
        Files.copy(original, copy, StandardCopyOption.REPLACE_EXISTING);

        // -1 means equal. Any other value is a byte index, not a line number.
        long diff = Files.mismatch(original, copy);
        System.out.println(diff == -1 ? "identical" : "differs at byte " + diff);
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public class SizeCheck {
    public static void main(String[] args) throws IOException {
        Path file = Path.of("out", "accented.txt");
        Files.createDirectories(file.getParent());

        // One accented char in UTF-8 takes two bytes.
        Files.writeString(file, "caf\u00E9\n", StandardCharsets.UTF_8);

        long bytes = Files.size(file);
        long chars = Files.readString(file, StandardCharsets.UTF_8).length();
        System.out.println("bytes=" + bytes + " chars=" + chars);

        // Always positive, so it can be used as an append guard.
        if (Files.size(file) > 0) {
            Files.writeString(file, "again\n", StandardOpenOption.APPEND);
        }
        System.out.println(Files.size(file) + " bytes after append");
    }
}
